      "body": "<table style=\"width:100%;border-collapse:collapse;margin:10px 0;font-size:15.5px;line-height:1.9\"><thead><tr><th style=\"border:1px solid #b9c6d4;background:#14365c;color:#fff;padding:8px 10px;text-align:right;font-weight:bold\">عدد السياقات</th><th style=\"border:1px solid #b9c6d4;background:#14365c;color:#fff;padding:8px 10px;text-align:right;font-weight:bold\">عدد الشركاء</th><th style=\"border:1px solid #b9c6d4;background:#14365c;color:#fff;padding:8px 10px;text-align:right;font-weight:bold\">خطة الأسبوعين القادمين</th></tr></thead><tbody><tr><td style=\"border:1px solid #b9c6d4;padding:8px 10px;vertical-align:top\"></td><td style=\"border:1px solid #b9c6d4;padding:8px 10px;vertical-align:top\">|</td></tr></tbody></table>"
